function parseCounts(form){
  form=String(form).replace(/[\s·×*]/g,'.');
  var i=0, n=form.length;
  function readFactor(){
    var map={};
    while(i<n){
      var c=form[i];
      if(c==='('){ i++; var g=readFactor();
        var num=1; if(i<n && /[0-9]/.test(form[i])){num=0;while(i<n&&/[0-9]/.test(form[i])){num=num*10+(form[i].charCodeAt(0)-48);i++;}}
        for(var k in g) map[k]=(map[k]||0)+g[k]*num;
        continue;
      }
      if(c===')'){ i++; break; }
      if(c==='.'){ i++;
        var mult=1; if(i<n && /[0-9]/.test(form[i])){mult=0;while(i<n&&/[0-9]/.test(form[i])){mult=mult*10+(form[i].charCodeAt(0)-48);i++;}}
        var rest=readFactor();
        for(var k in rest) map[k]=(map[k]||0)+rest[k]*mult;
        break;
      }
      if(/[A-Z]/.test(c)){
        var sym=c; i++;
        while(i<n && /[a-z]/.test(form[i])){ sym+=form[i]; i++; }
        var cnt=1; if(i<n && /[0-9]/.test(form[i])){cnt=0;while(i<n&&/[0-9]/.test(form[i])){cnt=cnt*10+(form[i].charCodeAt(0)-48);i++;}}
        map[sym]=(map[sym]||0)+cnt;
        continue;
      }
      i++;
    }
    return map;
  }
  return readFactor();
}

function parseEquation(eq){
  var sides=eq.split(/\s*(?:->|→|=)\s*/);
  if(sides.length!==2) return null;
  function side(s){ return s.split('+').map(function(p){ p=p.trim(); if(!p) return null;
    var m=p.match(/^(\d+)?\s*([A-Za-z0-9().]+)$/); if(!m) return null;
    var coeff=m[1]?parseInt(m[1],10):1; return {formula:m[2], coeff:coeff, counts:parseCounts(m[2])};
  }).filter(Boolean); }
  return {reactants:side(sides[0]), products:side(sides[1])};
}
function compute(eq, knownFormula, knownMoles){
  var p=parseEquation(eq); if(!p) return {error:"方程式格式错误"};
  var all=p.reactants.concat(p.products);
  var known=null; for(var i=0;i<all.length;i++) if(all[i].formula===knownFormula) known=all[i];
  if(!known) return {error:"未知物质 "+knownFormula};
  var out={};
  all.forEach(function(s){ if(s===known) return; out[s.formula]= knownMoles * s.coeff / known.coeff; });
  return {ok:true, out:out};
}
var EXPORTS={parseEquation:parseEquation, compute:compute};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StoichiometryForgePure = EXPORTS; }
